begin;
select plan(12);
insert into asset_analytics_cache(asset,price_history,history_updated_at) values('HISTORY_TEST','[{"time":1,"price":1}]',now()-interval '1 day');
select merge_asset_price_history('HISTORY_TEST',jsonb_build_array(jsonb_build_object('time',extract(epoch from now()-interval '10 minutes')::bigint*1000,'price',10)),now());
select is((select jsonb_array_length(price_history) from asset_analytics_cache where asset='HISTORY_TEST'),1,'repair retains genuine points and removes expired points');
select record_asset_price_samples(now(),jsonb_build_array(jsonb_build_object('asset','HISTORY_TEST','price','12')));
select merge_asset_price_history('HISTORY_TEST',jsonb_build_array(jsonb_build_object('time',extract(epoch from now()-interval '5 minutes')::bigint*1000,'price',11)),now());
select is((select jsonb_array_length(price_history) from asset_analytics_cache where asset='HISTORY_TEST'),3,'repair merges rather than overwrites a newer live sample');
select is((select price_history->-1->>'price' from asset_analytics_cache where asset='HISTORY_TEST'),'12','live mark is preserved');
select function_privs_are('public','merge_asset_price_history',array['text','jsonb','timestamptz'],'authenticated',array[]::text[],'browser cannot forge market history');
select function_privs_are('public','asset_history_updates',array['timestamptz','text[]'],'authenticated',array['EXECUTE'],'owner can load current history');
insert into market_history_backfills(asset,from_ms,completed_at) values('HISTORY_TEST',0,now());
update asset_analytics_cache set history_updated_at=now()-interval '1 hour' where asset='HISTORY_TEST';
select is(jsonb_array_length(asset_history_updates(now()-interval '1 minute',array['HISTORY_TEST'])->'rows'),1,'completion behind a live cursor is returned despite an older update timestamp');
select is(jsonb_array_length(asset_history_updates(null,array['HISTORY_TEST'])->'rows'->0->'price_history'),3,'initial hydration returns full history');
update market_history_backfills set completed_at=now()-interval '1 day' where asset='HISTORY_TEST';
update asset_analytics_cache set history_updated_at=now() where asset='HISTORY_TEST';
select is(jsonb_array_length(asset_history_updates(now()-interval '1 minute',array['HISTORY_TEST'])->'rows'->0->'price_history'),1,'routine poll returns only recent price samples');
select is(jsonb_array_length(asset_history_updates(null,array['NO_SUCH_ASSET'])->'rows'),0,'missing genuine history is not fabricated');
select is(has_table_privilege('authenticated','public.market_history_backfills','UPDATE'),false,'owner cannot forge repair completion');
select is(has_table_privilege('authenticated','public.market_history_repair_queue','SELECT'),false,'repair queue is service-only');
update asset_analytics_cache set price_history=jsonb_build_array(jsonb_build_object('time',extract(epoch from now()-interval '4 minutes')::bigint*1000,'price',12)) where asset='HISTORY_TEST';
select queue_asset_history_repairs(array['HISTORY_TEST']);
select ok((select from_ms>extract(epoch from now()-interval '20 minutes')::bigint*1000 from market_history_backfills where asset='HISTORY_TEST'),'a later outage starts a new repair instead of replaying the original gap');
select * from finish();
rollback;
